def buscar_exe(nombre):
    nombre = nombre.lower()
    userprofile = os.environ.get("USERPROFILE")
    carpetas = [
        os.environ.get("ProgramFiles"),
        os.environ.get("ProgramFiles(x86)"),
        os.path.join(userprofile, "AppData", "Local", "Programs") if userprofile else None,
        os.path.join(userprofile, "AppData", "Local") if userprofile else None
    ]
    for carpeta in carpetas:
        if not carpeta:
            continue
        if not os.path.exists(carpeta):
            continue
        for raiz, _, archivos in os.walk(carpeta):
            for archivo in archivos:
                if archivo.lower() == nombre + ".exe":
                    return {
                        "tipo": "exe",
                        "ruta": os.path.join(
                            raiz,
                            archivo
                        )
                    }
                if (
                    nombre in archivo.lower()
                    and archivo.lower().endswith(".exe")
                ):
                    return {
                        "tipo": "exe",
                        "ruta": os.path.join(
                            raiz,
                            archivo
                        )
                    }
    return None

