def buscar_acceso_directo(nombre):
    nombre = nombre.lower()
    programdata = os.environ.get("ProgramData")
    appdata = os.environ.get("APPDATA")
    carpetas = [
        os.path.join(programdata, "Microsoft", "Windows", "Start Menu", "Programs") if programdata else None,
        os.path.join(appdata, "Microsoft", "Windows", "Start Menu", "Programs") if appdata else None
    ]
    for carpeta in carpetas:
        if not carpeta or not os.path.exists(carpeta):
            continue
        for raiz, _, archivos in os.walk(carpeta):
            for archivo in archivos:
                if not archivo.lower().endswith(".lnk"):
                    continue
                archivo_sin_extension = archivo[:-4].lower()
                if nombre == archivo_sin_extension:
                    return {
                        "tipo": "exe",
                        "ruta": os.path.join(
                            raiz,
                            archivo
                        )
                    }
                if nombre in archivo_sin_extension:
                    return {
                        "tipo": "exe",
                        "ruta": os.path.join(
                            raiz,
                            archivo
                        )
                    }
    return None

